'use strict';
(()=>{
const C=window.YUNQUE,KEY='ludaria_yunque_v1',$=id=>document.getElementById(id),N=C.pages.length;
const fresh=()=>({version:1,page:0,visited:[0],fields:{},choices:C.quizzes.map(()=>null),seals:C.quizzes.map(()=>'pending'),hints:C.quizzes.map(()=>false),opened:[],tab:0,interest:null,components:[],timer:1080});
let state=fresh(),storageOK=true,feedback={},running=false,opener=null,toastTimeout;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s?.version===1){state.page=Number.isInteger(s.page)&&s.page>=0&&s.page<N?s.page:0;state.visited=Array.isArray(s.visited)?[...new Set(s.visited.filter(n=>Number.isInteger(n)&&n>=0&&n<N))]:[0];for(const k of Object.keys(C.fields))if(typeof s.fields?.[k]==='string')state.fields[k]=s.fields[k].slice(0,6000);for(let i=0;i<C.quizzes.length;i++){state.choices[i]=[0,1,2].includes(s.choices?.[i])?s.choices[i]:null;state.seals[i]=s.seals?.[i]==='assisted'?'assisted':s.seals?.[i]==='solved'&&state.choices[i]===C.quizzes[i].correct?'solved':'pending';state.hints[i]=s.hints?.[i]===true;}state.opened=Array.isArray(s.opened)?s.opened.filter(x=>C.dimensions.some(d=>d.id===x)):[];state.tab=[0,1,2].includes(s.tab)?s.tab:0;state.interest=[0,1].includes(s.interest)?s.interest:null;state.components=Array.isArray(s.components)?s.components.filter(x=>C.components.some(c=>c.id===x)):[];state.timer=Number.isInteger(s.timer)?Math.max(0,Math.min(1080,s.timer)):1080;}}catch(e){storageOK=false;}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}}
const b=(action,text,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const t=(action,text,attrs='')=>`<button class="text-button" data-action="${action}" ${attrs}>${text}</button>`;
const field=(id,scope='page')=>`<label class="field" for="field-${scope}-${id}">${C.fields[id].label}<textarea id="field-${scope}-${id}" data-field="${id}" maxlength="6000" rows="3" placeholder="${esc(C.fields[id].placeholder)}">${esc(state.fields[id])}</textarea></label>`;
const status=x=>x==='solved'?'Resuelto':x==='assisted'?'Apertura acompañada':'Por resolver';
const clock=()=>`${String(Math.floor(state.timer/60)).padStart(2,'0')}:${String(state.timer%60).padStart(2,'0')}`;
const title=n=>`<div class="section-title"><div><span class="eyebrow">LA FORJA · FORJADOR ONDAL · CREACIÓN</span><h2>${C.pages[n].title}</h2></div><span class="time-label">${C.pages[n].time} min · ${n>=3&&n<=6?'taller':'en clase'}</span></div><p class="lead">${C.pages[n].prompt}</p>`;
const scene=(n,body)=>`<section class="scene"><div class="scene-content wide">${title(n)}${body}<p class="note product">Producto: ${C.pages[n].product}</p></div></section>`;
const source=()=>`<p class="source-note">Diseño conectado con el canvas. Referencia: Werbach y Hunter (2012). Ejemplo y orientaciones de taller: elaboración propia. ${t('sources','Fuentes y alcance')}</p>`;
const tiles=(example=false)=>`<div class="canvas-grid ${example?'example':''}">${C.dimensions.map(d=>`<button class="canvas-tile" data-action="dimension" data-dim="${d.id}"><span class="eyebrow">${d.tag}${state.opened.includes(d.id)?' · CONSULTADA':''}</span><h3>${d.title}</h3><p>${example?d.model:d.question}</p></button>`).join('')}</div>`;
function quiz(i){const q=C.quizzes[i];return `<div class="split challenge-split"><div><h3 class="question-title">${q.question}</h3><div class="options">${q.options.map((o,n)=>`<button class="choice ${state.choices[i]===n?'selected':''}" data-action="choice" data-quiz="${i}" data-option="${n}" aria-pressed="${state.choices[i]===n}"><span class="choice-mark">${String.fromCharCode(65+n)}</span><span>${o.text}</span></button>`).join('')}</div><div class="actions">${b('check','Revisar mi decisión',`data-quiz="${i}"`)}${t('hint','Pedir una pista',`data-quiz="${i}"`)}</div>${feedback[i]?`<div class="feedback ${feedback[i].kind}" role="status" tabindex="-1">${feedback[i].text}</div>`:''}${state.hints[i]?`<p class="note">Pista: ${q.hint}</p>`:''}<p class="note">${t('assist','Abrir con acompañamiento',`data-quiz="${i}"`)} · Puedes seguir sin resolver.</p></div><aside class="lock-panel ${state.seals[i]!=='pending'?'open':''}"><div class="lock-glyph" aria-hidden="true"><svg viewBox="0 0 48 48"><rect x="10" y="21" width="28" height="22" rx="3"/><path d="M16 21v-7a8 8 0 0 1 16 0v7"/><circle cx="24" cy="31" r="2"/></svg></div><span class="eyebrow">CANDADO ${i+1}</span><h3>${q.name}</h3><p>${status(state.seals[i])}</p>${state.seals[i]!=='pending'?b('reward','Consultar la pauta',`data-quiz="${i}"`,true):'<p class="note">Pauta complementaria. Contenido y canvas siguen disponibles.</p>'}</aside></div>`;}
const groups=[['goal','behavior'],['players','loops'],['fun','tools']];
function page(n){switch(n){
case 0:return `<section class="scene"><div class="cover-content"><span class="eyebrow">MISIÓN SECUNDARIA 1 · MÓDULO 3 · SESIÓN 9</span><h1 class="cover-title">El <span>Yunque</span></h1><p class="lead">La idea encuentra su primera forma.<br>Forjemos una experiencia que pueda ponerse a prueba.</p><div class="cover-meta"><span class="small-line"></span><span>Forja del Arquitecto · Forjador Ondal</span></div><div class="actions">${b('begin','Comenzar el taller')}${b('guide','Guía docente','',true)}</div><p class="note">90 minutos sincrónicos · 90 asincrónicos · Creación</p></div></section>`;
case 1:return scene(n,`<div class="work-grid yunque-fields">${field('goal')}${field('behavior')}</div><div class="actions">${b('resources','Recursos del taller','',true)}${t('notebook','Abrir mi prototipo completo')}</div><p class="note">Trae tu primer canvas por el canal habitual o copia sus decisiones aquí. Misión secundaria optativa; instrucciones y recursos disponibles para todos.</p>`);
case 2:return scene(n,`<p class="note">CASO FICTICIO · Ciencias Naturales · Ciclo del agua. Una versión pequeña permite conversar el diseño antes de ampliarlo.</p>${tiles(true)}<div class="actions">${t('model','Leer el ejemplo breve completo')}${t('notebook','Elegir por dónde avanzar')}</div>`);
case 3:return scene(n,`<div class="split peer-split"><div class="workshop-panel"><div class="work-grid yunque-fields">${field('narrative')}${field('invitation')}</div><p class="note">Conecta la situación con el propósito que retomaste. El facilitador acompaña consultas individuales durante este bloque.</p><div class="actions">${t('dimension','Ver el ejemplo de narrativa','data-dim="narrative"')}</div></div><aside class="timer-box"><span class="eyebrow">BLOQUE DE TRABAJO</span><div class="timer" id="timer" role="timer" aria-label="Tiempo restante">${clock()}</div><div class="actions">${b('timer',running?'Pausar':'Iniciar')}${t('timer-reset','Reiniciar')}</div><p class="note">Tiempo orientativo. No cambia la pantalla; sigue el ritmo del facilitador.</p></aside></div>`);
case 4:return scene(n,`<div class="work-grid yunque-fields">${['mission','action','evidence','feedback'].map(id=>field(id)).join('')}</div><div class="actions">${t('dimension','Consultar la misión del ejemplo','data-dim="mission"')}${t('record','Conservar el borrador')}</div><p class="note">El producto y su explicación necesitan revisión humana. Registrar el avance no equivale a valorar el aprendizaje.</p>`);
case 5:return scene(n,`<div class="work-grid yunque-fields">${['progression','revisionPath','support'].map(id=>field(id)).join('')}</div><div class="actions">${t('dimension','Consultar la progresión del ejemplo','data-dim="progression"')}</div><p class="note">Los materiales esenciales siguen accesibles. Reserva los candados, si los usas, para recursos complementarios con apertura acompañada.</p>`);
case 6:return scene(n,`<div class="component-inventory" aria-label="Inventario local de recursos">${C.components.map(c=>`<button data-action="component" data-component="${c.id}" aria-pressed="${state.components.includes(c.id)}"><span class="mark" aria-hidden="true">${state.components.includes(c.id)?'✓':'+'}</span><strong>${c.title}</strong><small>${c.question}</small></button>`).join('')}</div><p class="note">Selección local para planificar; no es una lista obligatoria ni una puntuación de calidad.</p><div class="work-grid yunque-fields">${['components','recognition','feasibility'].map(id=>field(id)).join('')}</div><div class="actions">${t('dimension','Consultar los componentes del ejemplo','data-dim="components"')}</div>`);
case 7:return scene(n,quiz(0)+`<div class="actions">${t('notebook','Volver a mi misión')}</div>${source()}`);
case 8:return scene(n,`<div class="work-grid yunque-fields">${['advance','questions','next'].map(id=>field(id)).join('')}</div><div class="actions">${b('record','Conservar mi bitácora')}${b('resources','Canales y recursos','',true)}</div><p class="note">Este registro conserva prototipo y avance en el navegador. Compártelo por el canal que indique el facilitador; no se envía desde el HTML.</p>`);
case 9:return scene(n,`<div class="split"><article class="panel"><span class="eyebrow">90 MINUTOS ASINCRÓNICOS</span><h3>Desarrollar la primera versión</h3><p>Retoma narrativa, misión, progresión y componentes. Precisa reglas de reconocimiento, recursos y dudas para la revisión entre pares.</p><p class="note">Conserva tu versión para El Templado entre Pares. La carga procede de la ficha de la tesis; el facilitador acuerda el foco de trabajo.</p><div class="actions">${b('record','Conservar el prototipo')}${t('notebook','Seguir editando')}</div></article><div><span class="eyebrow">EL SIGUIENTE ENCUENTRO</span><h3 class="ceremony-title">Una forma para<br>conversar con otros.</h3><p class="lead">En El Templado entre Pares, las observaciones de dos compañeros ayudarán a ajustar el canvas.</p><p class="note">No hay recuperación de fragmento ni acreditación automática en este taller.</p></div></div>`);
}}

function render(focus=false){document.body.classList.toggle('is-cover',state.page===0);$('stage').innerHTML=page(state.page);$('page-count').textContent=`${state.page+1} / ${N}`;$('previous').disabled=state.page===0;$('next-label').textContent=state.page===N-1?'Mi canvas':'Siguiente';$('route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot ${state.visited.includes(i)?'visited':''} ${i===state.page?'current':''}" data-action="go" data-page="${i}" aria-label="Pantalla ${i+1}: ${p.title}" ${i===state.page?'aria-current="step"':''}></button>`).join('');$('seal-status').innerHTML=C.quizzes.map((q,i)=>`<button class="seal-dot ${state.seals[i]}" data-action="seal" data-quiz="${i}" aria-label="Candado ${q.name}: ${status(state.seals[i])}">${i+1}</button>`).join('');if(focus)$('stage').focus({preventScroll:true});}
function go(n){if(!Number.isInteger(n)||n<0||n>=N)return;if($('modal').open)$('modal').close();state.page=n;if(!state.visited.includes(n))state.visited.push(n);save();history.replaceState(null,'',`#pantalla-${n+1}`);render(true);window.scrollTo({top:0,behavior:'instant'});}
function modal(h,body){if(!$('modal').open)opener=document.activeElement;$('modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${h}</h2>${body}`;if(!$('modal').open)$('modal').showModal();$('modal-title').focus({preventScroll:true});}
function close(){const old=opener,d=old?.dataset?{...old.dataset}:null;$('modal').close();render();if(old?.isConnected)old.focus({preventScroll:true});else if(d){[...document.querySelectorAll('[data-action]')].find(x=>Object.entries(d).every(([k,v])=>x.dataset[k]===v))?.focus({preventScroll:true});}}
function toast(msg){clearTimeout(toastTimeout);$('toast').textContent=msg;$('toast').hidden=false;toastTimeout=setTimeout(()=>$('toast').hidden=true,4000);}
function reward(i){modal('La pauta de '+C.quizzes[i].name,`<p>${status(state.seals[i])}. Recurso complementario para conversar.</p><ul class="reward-list">${C.quizzes[i].reward.map(x=>`<li>${x}</li>`).join('')}</ul><p>${C.quizzes[i].options[C.quizzes[i].correct].why}</p><p class="note">Orientaciones didácticas de esta práctica. No es una rúbrica de tesis ni una calificación.</p>`);}
function dimension(id){const d=C.dimensions.find(x=>x.id===id);if(!d)return;if(!state.opened.includes(id))state.opened.push(id);save();modal(d.tag+' · '+d.title,`<p>${d.body}</p><div class="case-panel" style="margin-top:20px"><span class="eyebrow">MODELO FICTICIO · EL CICLO DEL AGUA</span><p>${d.model}</p></div><p class="note">${d.detail}</p><div class="actions">${t('edit','Anotar esta decisión en mi canvas',`data-field-id="${id}"`)}${t('sources','Referencia y alcance')}</div>`);}
function model(){modal('Un ejemplo breve de prototipo',`<p>Ciencias Naturales · caso ficticio de taller. Ejemplo propio para conversar una primera versión; no documenta una intervención ni resultados reales.</p><div class="modal-canvas">${C.dimensions.map(d=>`<article><span class="eyebrow">${d.tag}</span><h3>${d.title}</h3><p>${d.model}</p><p class="note">${d.detail}</p></article>`).join('')}</div>`);}
function sources(){modal('Fuentes y alcance',C.sources.map(s=>`<h3>${s.title}</h3><p>${esc(s.apa)}</p><p class="note">${esc(s.use)}</p>${s.url?`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Consultar fuente primaria</a></p>`:''}`).join('')+'<p class="note">Canvas, casos, preguntas y secuencias: elaboración didáctica propia. Arte generado específicamente para Ludaria; esquemas y canvas construidos con código.</p>');}
function textRecord(){return ['BUSCADORES DE LA GAMIFICACIÓN PERDIDA','El Yunque · Sesión 9 · Misión secundaria 1 · Módulo 3','Fecha: '+new Date().toLocaleDateString('es-CL'),'',...Object.entries(C.fields).flatMap(([id,f])=>[f.label.toUpperCase(),state.fields[id]||'(Sin registro)','']),'PRÁCTICA LOCAL',...C.quizzes.flatMap((q,i)=>[q.name+': '+status(state.seals[i]),'Decisión: '+(q.options[state.choices[i]]?.text||'Sin elegir'),'Pista consultada: '+(state.hints[i]?'Sí':'No')]),'Decisiones consultadas: '+(state.opened.map(id=>C.dimensions.find(d=>d.id===id).tag).join(', ')||'Ninguna'),'Recursos considerados: '+(state.components.map(id=>C.components.find(c=>c.id===id).title).join(', ')||'Sin seleccionar'),'','Este prototipo y su bitácora no se han enviado desde el HTML. Requieren revisión humana; no acreditan Códigos del Saber.','','FUENTES',...C.sources.map(s=>s.apa)].join('\n');}
function record(){modal('Bitácora y prototipo del Yunque',`<p>Conserva el prototipo y la huella del taller por el canal indicado en clase.</p><label class="field" for="export-text">Registro completo<textarea id="export-text" readonly rows="12">${esc(textRecord())}</textarea></label><div class="actions">${b('copy','Copiar registro')}${b('download','Descargar TXT','',true)}</div><p class="note">Si el marco restringe copia o descarga, selecciona el texto o abre la misión en otra pestaña.</p>`);}
function notebook(){modal('Mi prototipo editable',`<p>El prototipo y sus decisiones están siempre disponibles. Edita la parte que necesitas desarrollar.</p><div class="work-grid">${Object.keys(C.fields).map(id=>field(id,'book')).join('')}</div><div class="actions">${b('record','Ver registro completo')}</div><p class="note">Borrador local por dispositivo. ${storageOK?'Guardado disponible.':'Guardado restringido: conserva el registro visible.'} Sin envío ni autocalificación.</p>`);}
function guide(){modal('Acompañar El Yunque',`<p>Secundaria 1 del módulo 3. Forja · Ondal · Creación. Objetivo: prototipar la experiencia gamificada personal.</p><ol class="complete-list">${C.pages.map(p=>`<li><strong>${p.title} · ${p.time} min.</strong> ${p.prompt}<br>Producto: ${p.product}</li>`).join('')}</ol><p>90 minutos sincrónicos y 90 asincrónicos según la tesis. El facilitador acompaña consultas individuales y organiza los bloques de trabajo. Narrativa, misión, progresión y componentes se desarrollan en el prototipo personal.</p><p>Revise explicaciones y productos; los sellos son prácticas complementarias. La plantilla y el caso son didácticos y no reproducen instrumentos de evaluación. Canvas y bitácora externos necesitan URLs reales; las alternativas locales ya están disponibles.</p>`);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,i=Number(el.dataset.quiz),o=Number(el.dataset.option);switch(a){
case 'begin':go(1);break;case 'go':go(Number(el.dataset.page));break;case 'close':close();break;
case 'map':modal('Los pasos del taller',`<p>Acceso libre a todas las pantallas. ${state.visited.length}/${N} visitadas; recorrido local.</p><div class="modal-grid">${C.pages.map((p,n)=>`<button class="map-item" data-action="go" data-page="${n}"><span>${n+1}</span>${p.title}</button>`).join('')}</div><div class="actions">${t('reset-ask','Reiniciar esta misión')}</div>`);break;
case 'guide':guide();break;case 'sources':sources();break;case 'notebook':notebook();break;case 'record':record();break;case 'model':model();break;case 'dimension':dimension(el.dataset.dim);break;
case 'edit':if(C.fields[el.dataset.fieldId])modal(C.fields[el.dataset.fieldId].label,field(el.dataset.fieldId,'notes')+'<p class="note">Anotación local editable. No hay respuesta automática ni envío.</p>');break;
case 'choice':state.choices[i]=o;state.seals[i]='pending';delete feedback[i];save();render();document.querySelector(`[data-action="choice"][data-quiz="${i}"][data-option="${o}"]`)?.focus({preventScroll:true});break;
case 'check':if(state.choices[i]===null){feedback[i]={kind:'hint',text:'Elige una alternativa antes de revisar. Puedes pedir una pista o consultar la pauta con apoyo.'};render();document.querySelector('.feedback')?.focus({preventScroll:true});break;}if(state.choices[i]===C.quizzes[i].correct){state.seals[i]='solved';save();render();reward(i);}else{feedback[i]={kind:'error',text:C.quizzes[i].options[state.choices[i]].why+' Puedes revisar sin penalización.'};render();document.querySelector('.feedback')?.focus({preventScroll:true});}break;
case 'hint':state.hints[i]=true;save();render();break;
case 'assist':modal('Abrir con acompañamiento',`<p>Conversen la práctica con apoyo. La pauta complementaria puede abrirse y el sello lo distinguirá.</p><div class="actions">${b('assist-confirm','Abrir pauta con apoyo',`data-quiz="${i}"`)}${b('close','Volver a intentar','',true)}</div>`);break;
case 'assist-confirm':state.seals[i]='assisted';save();render();reward(i);break;
case 'seal':if(state.seals[i]!=='pending')reward(i);else go([7][i]);break;case 'reward':reward(i);break;
case 'component':{const id=el.dataset.component;if(!C.components.some(c=>c.id===id))break;state.components=state.components.includes(id)?state.components.filter(x=>x!==id):[...state.components,id];save();render();document.querySelector(`[data-action="component"][data-component="${id}"]`)?.focus({preventScroll:true});break;}
case 'resources':{const links=[['canvasExterno','Canvas externo'],['bitacoraExterna','Bitácora externa']];modal('Recursos del taller',links.map(([key,name])=>{const url=window.YUNQUE_CONFIG?.[key];return `<h3>${name}</h3>`+(typeof url==='string'&&/^https:\/\//.test(url)?`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Abrir ${name.toLowerCase()}</a></p><p class="note">El HTML no verifica entregas en ese recurso.</p>`:'<p class="note">Enlace pendiente de configurar. El prototipo y la bitácora locales permiten conservar el trabajo.</p>');}).join('')+`<div class="actions">${b('notebook','Editar el prototipo local')}${b('record','Conservar el registro','',true)}</div>`);break;}
case 'tab':state.tab=o;save();render();$('tab-'+o).focus({preventScroll:true});break;
case 'timer':if(state.timer===0)state.timer=1080;running=!running;save();render();break;case 'timer-reset':running=false;state.timer=1080;save();render();break;
case 'copy':try{if(!navigator.clipboard?.writeText)throw Error();await Promise.race([navigator.clipboard.writeText(textRecord()),new Promise((_,rej)=>setTimeout(()=>rej(Error()),3500))]);toast('Registro copiado.');}catch(err){$('export-text')?.focus();$('export-text')?.select();toast('Selecciona el registro y usa Copiar en tu dispositivo.');}break;
case 'download':{const url=URL.createObjectURL(new Blob(['\ufeff'+textRecord()],{type:'text/plain;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='Canvas_Los_Planos_del_Arquitecto.txt';document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Descarga solicitada; también puedes copiar el registro visible.');break;}
case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Abre la clase en una pestaña para usar pantalla completa.'));break;
case 'reset-ask':modal('Reiniciar esta misión',`<p>Se borrará únicamente el prototipo de El Yunque en este dispositivo. Conserva el registro primero.</p><div class="actions">${b('reset','Reiniciar')}${b('record','Ver registro antes','',true)}</div>`);break;
case 'reset':state=fresh();running=false;feedback={};save();go(0);break;
}});
document.addEventListener('input',e=>{const id=e.target.dataset.field;if(C.fields[id]){state.fields[id]=e.target.value;save();}});
$('previous').addEventListener('click',()=>go(state.page-1));$('next').addEventListener('click',()=>state.page===N-1?record():go(state.page+1));$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||$('modal').open)return;if(e.target.closest('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();state.tab=e.key==='Home'?0:e.key==='End'?2:(state.tab+(e.key==='ArrowRight'?1:2))%3;save();render();$('tab-'+state.tab).focus();return;}if(e.target.closest('input,textarea,select,button,a'))return;if(e.key==='ArrowRight'){e.preventDefault();go(state.page+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.page-1);}});
window.addEventListener('hashchange',()=>{const m=/^#pantalla-(\d+)$/.exec(location.hash);if(m)go(Number(m[1])-1);});
setInterval(()=>{if(running&&state.page===3){state.timer=Math.max(0,state.timer-1);save();if($('timer'))$('timer').textContent=clock();if(state.timer===0){running=false;render();toast('Terminó el tiempo orientativo; pueden continuar conversando.');}}},1000);
if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('fireflies').innerHTML=Array.from({length:10},(_,i)=>`<i class="fly" style="left:${(i*37+9)%100}%;top:${(i*19+13)%100}%;animation-delay:-${i}s"></i>`).join('');
const start=/^#pantalla-(\d+)$/.exec(location.hash);if(start&&Number(start[1])>=1&&Number(start[1])<=N)state.page=Number(start[1])-1;if(!state.visited.includes(state.page))state.visited.push(state.page);save();render();
})();
